const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");

// Icon imports
const { FaArrowUp, FaArrowDown, FaPython, FaTrophy, FaChartLine, FaLightbulb, FaDatabase, FaCogs } = require("react-icons/fa");
const { MdTrendingUp, MdTrendingDown } = require("react-icons/md");

function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Color palette — Midnight Executive with data accents
const C = {
  navy: "1A1F3D",
  darkNavy: "12152B",
  midBlue: "2C3E6B",
  accent: "3B82F6",    // bright blue accent
  accentLight: "60A5FA",
  green: "22C55E",
  red: "EF4444",
  orange: "F59E0B",
  gold: "FBBF24",
  white: "FFFFFF",
  offWhite: "F1F5F9",
  lightGray: "E2E8F0",
  medGray: "94A3B8",
  darkGray: "64748B",
  text: "1E293B",
  textLight: "CBD5E1",
  textMuted: "94A3B8",
  cardBg: "1E2548",
  slideLight: "F8FAFC",
};

const FONT_H = "Trebuchet MS";
const FONT_B = "Calibri";

// Factory functions for reusable option objects (PptxGenJS mutates in-place)
const makeShadow = () => ({ type: "outer", color: "000000", blur: 8, offset: 3, angle: 135, opacity: 0.12 });
const makeCardShadow = () => ({ type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.10 });

async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Data Analytics Team";
  pres.title = "TIOBE Index March 2026: Programming Language Popularity Rankings and Trends";

  // Pre-render icons
  const iconUp = await iconToBase64Png(MdTrendingUp, "#22C55E", 256);
  const iconDown = await iconToBase64Png(MdTrendingDown, "#EF4444", 256);
  const iconTrophy = await iconToBase64Png(FaTrophy, "#FBBF24", 256);
  const iconChart = await iconToBase64Png(FaChartLine, "#3B82F6", 256);
  const iconBulb = await iconToBase64Png(FaLightbulb, "#F59E0B", 256);
  const iconCogs = await iconToBase64Png(FaCogs, "#94A3B8", 256);
  const iconUpWhite = await iconToBase64Png(MdTrendingUp, "#FFFFFF", 256);
  const iconDownWhite = await iconToBase64Png(MdTrendingDown, "#FFFFFF", 256);
  const iconTrophyWhite = await iconToBase64Png(FaTrophy, "#FFFFFF", 256);
  const iconChartWhite = await iconToBase64Png(FaChartLine, "#FFFFFF", 256);

  // =====================================================
  // SLIDE 1: Title Slide (dark)
  // =====================================================
  const s1 = pres.addSlide();
  s1.background = { color: C.darkNavy };

  // Subtle geometric accent - large transparent circle
  s1.addShape(pres.shapes.OVAL, {
    x: 6.8, y: -1.2, w: 5, h: 5,
    fill: { color: C.accent, transparency: 92 }
  });
  s1.addShape(pres.shapes.OVAL, {
    x: 7.8, y: 2.5, w: 3.5, h: 3.5,
    fill: { color: C.accentLight, transparency: 94 }
  });

  // Accent bar top
  s1.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.accent }
  });

  // Title
  s1.addText("TIOBE Index March 2026", {
    x: 0.8, y: 1.1, w: 7.5, h: 0.7,
    fontSize: 38, fontFace: FONT_H, color: C.white, bold: true, margin: 0
  });

  // Subtitle
  s1.addText("How 20+ Search Engines Rank the World's Programming Languages", {
    x: 0.8, y: 1.85, w: 7.5, h: 0.55,
    fontSize: 20, fontFace: FONT_B, color: C.accentLight, margin: 0
  });

  // Methodology description
  s1.addShape(pres.shapes.RECTANGLE, {
    x: 0.8, y: 2.7, w: 0.06, h: 1.3,
    fill: { color: C.accent }
  });
  s1.addText(
    "The TIOBE Programming Community Index measures programming language popularity based on search-engine hit counts across Google, Bing, Wikipedia, Amazon, and 20+ other sites. Updated monthly since 2001, it reflects how much a language is discussed and sought after on the public internet.",
    {
      x: 1.1, y: 2.7, w: 6.8, h: 1.3,
      fontSize: 13, fontFace: FONT_B, color: C.textLight, lineSpacingMultiple: 1.35, margin: 0
    }
  );

  // Key stat callouts at bottom
  const statY = 4.4;
  const stats = [
    { label: "Languages Tracked", value: "50+", x: 0.8 },
    { label: "Search Engines", value: "20+", x: 3.2 },
    { label: "Years of Data", value: "25", x: 5.6 },
    { label: "Monthly Updates", value: "300+", x: 8.0 },
  ];
  stats.forEach(s => {
    s1.addText(s.value, {
      x: s.x, y: statY, w: 1.8, h: 0.5,
      fontSize: 28, fontFace: FONT_H, color: C.accent, bold: true, margin: 0
    });
    s1.addText(s.label, {
      x: s.x, y: statY + 0.45, w: 1.8, h: 0.3,
      fontSize: 11, fontFace: FONT_B, color: C.medGray, margin: 0
    });
  });

  // Source line
  s1.addText("Source: tiobe.com/tiobe-index | Data captured April 10, 2026", {
    x: 0.8, y: 5.15, w: 8, h: 0.3,
    fontSize: 9, fontFace: FONT_B, color: C.darkGray, margin: 0
  });

  // =====================================================
  // SLIDE 2: Top 20 Rankings (light background, table)
  // =====================================================
  const s2 = pres.addSlide();
  s2.background = { color: C.slideLight };

  // Top accent bar
  s2.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.04,
    fill: { color: C.accent }
  });

  s2.addText("Python Holds #1 at 21.25% but C Surges to #2 with the Largest Gain", {
    x: 0.6, y: 0.25, w: 8.8, h: 0.55,
    fontSize: 22, fontFace: FONT_H, color: C.text, bold: true, margin: 0
  });

  s2.addText("Top 20 Programming Languages — March 2026 TIOBE Index", {
    x: 0.6, y: 0.78, w: 8, h: 0.3,
    fontSize: 11, fontFace: FONT_B, color: C.darkGray, margin: 0
  });

  // Table data
  const rankings = [
    [1,1,"Python","21.25%","-2.59%"],
    [2,4,"C","11.55%","+2.02%"],
    [3,2,"C++","8.18%","-2.90%"],
    [4,3,"Java","7.99%","-2.37%"],
    [5,5,"C#","6.36%","+1.49%"],
    [6,6,"JavaScript","3.45%","-0.01%"],
    [7,9,"Visual Basic","2.50%","-0.02%"],
    [8,8,"SQL","2.00%","-0.57%"],
    [9,16,"R","1.88%","+0.94%"],
    [10,10,"Delphi/Obj Pascal","1.80%","-0.36%"],
    [11,24,"Perl","1.75%","+1.05%"],
    [12,12,"Scratch","1.63%","-0.03%"],
    [13,11,"Fortran","1.45%","-0.25%"],
    [14,14,"Rust","1.31%","+0.09%"],
    [15,15,"MATLAB","1.29%","+0.31%"],
    [16,7,"Go","1.29%","-1.49%"],
    [17,17,"Assembly","1.29%","+0.42%"],
    [18,13,"PHP","1.23%","-0.25%"],
    [19,18,"Ada","1.10%","+0.25%"],
    [20,26,"Swift","1.04%","+0.44%"],
  ];

  const headerOpts = { fill: { color: C.navy }, color: C.white, bold: true, fontSize: 9, fontFace: FONT_B, align: "center", valign: "middle" };
  const tableHeader = [
    { text: "Rank", options: { ...headerOpts } },
    { text: "2025", options: { ...headerOpts } },
    { text: "Language", options: { ...headerOpts, align: "left" } },
    { text: "Rating", options: { ...headerOpts } },
    { text: "YoY Change", options: { ...headerOpts } },
  ];

  const tableRows = rankings.map((r, i) => {
    const isEven = i % 2 === 0;
    const rowFill = isEven ? C.white : "EEF2F7";
    const yoyVal = parseFloat(r[4]);
    const yoyColor = yoyVal > 0 ? C.green : yoyVal < 0 ? C.red : C.text;
    const cellBase = { fill: { color: rowFill }, fontSize: 9, fontFace: FONT_B, valign: "middle" };

    // Highlight top 5
    const isTop5 = r[0] <= 5;
    const langStyle = isTop5 ? { bold: true, color: C.navy } : { color: C.text };

    return [
      { text: String(r[0]), options: { ...cellBase, align: "center", bold: true, color: C.navy } },
      { text: String(r[1]), options: { ...cellBase, align: "center", color: C.darkGray } },
      { text: r[2], options: { ...cellBase, align: "left", ...langStyle } },
      { text: r[3], options: { ...cellBase, align: "center", color: C.text } },
      { text: r[4], options: { ...cellBase, align: "center", color: yoyColor, bold: true } },
    ];
  });

  s2.addTable([tableHeader, ...tableRows], {
    x: 0.4, y: 1.15, w: 5.5,
    colW: [0.55, 0.55, 1.8, 0.85, 0.95],
    rowH: [0.25, ...Array(20).fill(0.2)],
    border: { pt: 0.5, color: C.lightGray },
    margin: [2, 4, 2, 4],
  });

  // Right side: key insights cards
  const cardX = 6.2;
  const cardW = 3.5;

  // Insight card 1: Python dominance
  s2.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 1.15, w: cardW, h: 1.2,
    fill: { color: C.white }, shadow: makeCardShadow()
  });
  s2.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 1.15, w: 0.07, h: 1.2,
    fill: { color: C.accent }
  });
  s2.addText("21.25%", {
    x: cardX + 0.25, y: 1.2, w: 2, h: 0.45,
    fontSize: 28, fontFace: FONT_H, color: C.accent, bold: true, margin: 0
  });
  s2.addText("Python leads, but lost 2.59 points YoY — the largest drop among the top 5.", {
    x: cardX + 0.25, y: 1.65, w: 3.0, h: 0.6,
    fontSize: 10, fontFace: FONT_B, color: C.darkGray, lineSpacingMultiple: 1.3, margin: 0
  });

  // Insight card 2: C surge
  s2.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 2.55, w: cardW, h: 1.2,
    fill: { color: C.white }, shadow: makeCardShadow()
  });
  s2.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 2.55, w: 0.07, h: 1.2,
    fill: { color: C.green }
  });
  s2.addText("+2.02%", {
    x: cardX + 0.25, y: 2.6, w: 2, h: 0.45,
    fontSize: 28, fontFace: FONT_H, color: C.green, bold: true, margin: 0
  });
  s2.addText("C surged from 4th to 2nd, posting the biggest gain among top languages.", {
    x: cardX + 0.25, y: 3.05, w: 3.0, h: 0.6,
    fontSize: 10, fontFace: FONT_B, color: C.darkGray, lineSpacingMultiple: 1.3, margin: 0
  });

  // Insight card 3: Top 4 concentration
  s2.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 3.95, w: cardW, h: 1.2,
    fill: { color: C.white }, shadow: makeCardShadow()
  });
  s2.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: 3.95, w: 0.07, h: 1.2,
    fill: { color: C.orange }
  });
  s2.addText("48.97%", {
    x: cardX + 0.25, y: 4.0, w: 2, h: 0.45,
    fontSize: 28, fontFace: FONT_H, color: C.orange, bold: true, margin: 0
  });
  s2.addText("Top 4 languages hold nearly half the total index — extreme concentration.", {
    x: cardX + 0.25, y: 4.45, w: 3.0, h: 0.6,
    fontSize: 10, fontFace: FONT_B, color: C.darkGray, lineSpacingMultiple: 1.3, margin: 0
  });

  // Source
