  // SLIDE 3: Biggest Movers (dark, gainers vs losers)
  // =====================================================
  const s3 = pres.addSlide();
  s3.background = { color: C.darkNavy };

  s3.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.04,
    fill: { color: C.accent }
  });

  s3.addText("Perl Jumps 13 Spots, R Climbs 7, and Go Drops 9 — The Biggest Rank Shifts of 2026", {
    x: 0.6, y: 0.25, w: 8.8, h: 0.55,
    fontSize: 20, fontFace: FONT_H, color: C.white, bold: true, margin: 0
  });

  // Gainers column header
  s3.addImage({ data: iconUp, x: 0.6, y: 1.0, w: 0.3, h: 0.3 });
  s3.addText("GAINERS", {
    x: 1.0, y: 1.0, w: 2, h: 0.35,
    fontSize: 14, fontFace: FONT_H, color: C.green, bold: true, charSpacing: 3, margin: 0
  });

