    fontSize: 14, fontFace: FONT_H, color: C.red, bold: true, charSpacing: 3, margin: 0
  });

  // Divider line
  s3.addShape(pres.shapes.LINE, {
    x: 4.95, y: 1.0, w: 0, h: 4.1,
    line: { color: C.midBlue, width: 1.5 }
  });

  // Gainer cards
  const gainers = [
    { lang: "Perl", from: "24th", to: "11th", delta: "+1.05%", spots: "+13 spots", note: "Surprising revival in infrastructure and text processing" },
    { lang: "R", from: "16th", to: "9th", delta: "+0.94%", spots: "+7 spots", note: "Strong growth in statistical computing and data science" },
    { lang: "Swift", from: "26th", to: "20th", delta: "+0.44%", spots: "+6 spots", note: "Re-enters top 20 driven by Apple platform growth" },
    { lang: "Assembly", from: "17th", to: "17th", delta: "+0.42%", spots: "Holds", note: "Embedded systems and low-level demand remains steady" },
