  const losers = [
    { lang: "Go", from: "7th", to: "16th", delta: "-1.49%", spots: "-9 spots", note: "Sharpest drop of any top-20 language; possible Rust displacement" },
    { lang: "C++", from: "2nd", to: "3rd", delta: "-2.90%", spots: "-1 spot", note: "Largest absolute rating loss despite holding 3rd place" },
