    { lang: "C++", from: "2nd", to: "3rd", delta: "-2.90%", spots: "-1 spot", note: "Largest absolute rating loss despite holding 3rd place" },
    { lang: "Java", from: "3rd", to: "4th", delta: "-2.37%", spots: "-1 spot", note: "Continued long-term decline from its mid-2000s dominance" },
    { lang: "PHP", from: "13th", to: "18th", delta: "-0.25%", spots: "-5 spots", note: "Gradual decline as web frameworks diversify" },
  ];

  gainers.forEach((g, i) => {
