  { year: "2022", winner: "C++", isPython: false },
  { year: "2021", winner: "Python", isPython: true },
  { year: "2020", winner: "Python", isPython: true },
  { year: "2019", winner: "C", isPython: false },
  { year: "2018", winner: "Python", isPython: true },
  { year: "2016", winner: "Go", isPython: false },
];

// 3x3 grid of award cards
hofData.forEach((h, i) => {
  const col = i % 3;
  const row = Math.floor(i / 3);
  const cx = 0.6 + col * 3.1;
  const cy = 1.35 + row * 1.35;

  const cardColor = h.isPython ? "1E2F5A" : C.cardBg;
  const accentColor = h.isPython ? C.gold : C.medGray;

  s5.addShape(pres.shapes.RECTANGLE, {
    x: cx, y: cy, w: 2.8, h: 1.1,
    fill: { color: cardColor }
  });
  // Top accent
  s5.addShape(pres.shapes.RECTANGLE, {
    x: cx, y: cy, w: 2.8, h: 0.05,
    fill: { color: accentColor }
  });

  s5.addText(h.year, {
    x: cx + 0.2, y: cy + 0.15, w: 1.0, h: 0.35,
    fontSize: 22, fontFace: FONT_H, color: accentColor, bold: true, margin: 0
  });
  s5.addText(h.winner, {
    x: cx + 0.2, y: cy + 0.55, w: 2.0, h: 0.35,
    fontSize: 16, fontFace: FONT_B, color: C.white, bold: h.isPython, margin: 0
  });
  if (h.isPython) {
    s5.addImage({ data: iconTrophy, x: cx + 2.2, y: cy + 0.3, w: 0.35, h: 0.35 });
  }
});

// Python total wins callout on right
s5.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 4.15, w: 3.3, h: 0.95,
  fill: { color: "1E2F5A" }
});
s5.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 4.15, w: 0.06, h: 0.95,
  fill: { color: C.gold }
});
s5.addText("Python: 6 wins total", {
  x: 6.55, y: 4.2, w: 2.8, h: 0.3,
  fontSize: 14, fontFace: FONT_H, color: C.gold, bold: true, margin: 0
});
s5.addText("2007, 2010, 2018, 2020, 2021, 2024", {
  x: 6.55, y: 4.55, w: 2.8, h: 0.25,
  fontSize: 10, fontFace: FONT_B, color: C.textLight, margin: 0
});
s5.addText("C# won in 2023 and 2025, reflecting .NET ecosystem growth.", {
  x: 6.55, y: 4.8, w: 2.8, h: 0.25,
  fontSize: 9, fontFace: FONT_B, color: C.textMuted, margin: 0
});

