  { year: "2019", winner: "C", isPython: false },
  { year: "2018", winner: "Python", isPython: true },
  { year: "2016", winner: "Go", isPython: false },
];

// Left side: 3-column x 3-row grid of compact award cards
hofData.forEach((h, i) => {
  const col = i % 3;
  const row = Math.floor(i / 3);
  const cx = 0.6 + col * 2.15;
  const cy = 1.3 + row * 1.25;

  const cardColor = h.isPython ? "1E2F5A" : C.cardBg;
  const accentColor = h.isPython ? C.gold : C.medGray;

  s5.addShape(pres.shapes.RECTANGLE, {
    x: cx, y: cy, w: 1.95, h: 1.0,
    fill: { color: cardColor }
  });
  s5.addShape(pres.shapes.RECTANGLE, {
    x: cx, y: cy, w: 1.95, h: 0.05,
    fill: { color: accentColor }
  });

  s5.addText(h.year, {
    x: cx + 0.15, y: cy + 0.15, w: 1.0, h: 0.32,
    fontSize: 20, fontFace: FONT_H, color: accentColor, bold: true, margin: 0
  });
  s5.addText(h.winner, {
    x: cx + 0.15, y: cy + 0.52, w: 1.3, h: 0.32,
    fontSize: 15, fontFace: FONT_B, color: C.white, bold: h.isPython, margin: 0
  });
  if (h.isPython) {
    s5.addImage({ data: iconTrophy, x: cx + 1.45, y: cy + 0.3, w: 0.35, h: 0.35 });
  }
});

// Right side: Python summary callout
const sumX = 7.1;
s5.addShape(pres.shapes.RECTANGLE, {
  x: sumX, y: 1.3, w: 2.5, h: 4.0,
  fill: { color: "1E2F5A" }
});
s5.addShape(pres.shapes.RECTANGLE, {
  x: sumX, y: 1.3, w: 2.5, h: 0.05,
  fill: { color: C.gold }
});

s5.addImage({ data: iconTrophy, x: sumX + 0.85, y: 1.55, w: 0.7, h: 0.7 });
s5.addText("6", {
  x: sumX + 0.2, y: 2.35, w: 2.1, h: 0.55,
  fontSize: 48, fontFace: FONT_H, color: C.gold, bold: true, align: "center", margin: 0
});
s5.addText("Python Wins", {
  x: sumX + 0.2, y: 2.85, w: 2.1, h: 0.3,
  fontSize: 16, fontFace: FONT_H, color: C.white, bold: true, align: "center", margin: 0
});
s5.addText("2007, 2010, 2018,\n2020, 2021, 2024", {
  x: sumX + 0.2, y: 3.25, w: 2.1, h: 0.5,
  fontSize: 11, fontFace: FONT_B, color: C.textLight, align: "center", margin: 0
});

// Divider
s5.addShape(pres.shapes.LINE, {
  x: sumX + 0.3, y: 3.9, w: 1.9, h: 0,
  line: { color: C.midBlue, width: 1 }
});

s5.addText("C# won in 2023 and 2025, reflecting continued .NET ecosystem growth.", {
  x: sumX + 0.2, y: 4.05, w: 2.1, h: 0.5,
  fontSize: 9.5, fontFace: FONT_B, color: C.textMuted, align: "center", lineSpacingMultiple: 1.3, margin: 0
});
s5.addText("Go's 2016 win preceded its current decline to 16th.", {
  x: sumX + 0.2, y: 4.55, w: 2.1, h: 0.4,
  fontSize: 9.5, fontFace: FONT_B, color: C.textMuted, align: "center", lineSpacingMultiple: 1.3, margin: 0
});

